	title 'COMMON       GS ROM 3.0'*****************************************************************			   **              Common		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1988	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ***************************************************************************************************************************************** Change History** 10 Jun 88	Steven Glass** This file contains the strip code again.** The 0-strip routines do not fall through the common code but rather* short cut the process saving cycles.  This should get the * UCSD Pascal working again.***********************************************************************	include '::sys.equs.asm';-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY ErrOut	ENTRY oBusyErr	ENTRY oErrOut	ENTRY oErrOut0****************************************************************** NotImp*****************************************************************	EXPORT NotImpNotImp	PROC	ldx #$FFFF	jmp oErrOut0	ENDP****************************************************************** EndCall Routines.** Functions exit through the EndCall routines.  These routines* fix the stack by moving the RTL addresses up and stripping* off any input parameters.** The number of bytes to strip off the stack is passed in the* y-register.** There are 8 end call routines**       EndCall	   Pulls D off stack before cleaning up.  Sets*	   a-reg to zero and clears carry.*       oEndCall	   Does not pull D off the stack before*	   cleaning up.  Sets a-reg to zero and	clears*	   carry.*       ErrOut	   Pulls D off stack, cleans up and returns*	   error code passed in x-register, setting*	   carry if x is not zero.*       oErrOut	   Does not pull D off stack before cleaning up.*	   returns error code passed in x-register,*	   setting carry if	x is not zero.**       BusyEC	   Decrements the busy flag, pulls D off stack*	   and cleans up.*       oBusyEC	   Decrements the busy flag, does not pull D off stack*	   and cleans up.*       BusyErr	   Decrements the busy flag, pulls D off stack,*	   cleans up and returns error code passed in*	   x-register, setting the carry if x is not zero.*       oBusyErr	   Decrements the busy flag, does not pull D off*	   the stack, cleans up and returns error code passed*	   in x-register.*****************************************************************	EXPORT oEndCall0oEndCall0	PROC	phd	EXPORT EndCall0EndCall0		;       	ldx #0	EXPORT ErrOut0ErrOut0		;       	pld	EXPORT oErrOut0oErrOut0		;       	txa	cmp #1	rtl	ENDP	EXPORT oBusyEC0oBusyEC0	PROC	phd	EXPORT BusyEC0BusyEC0		;       	ldx #0	EXPORT BusyErr0BusyErr0		;       	pld	EXPORT oBusyErr0oBusyErr0		;       	txa	cmp #1	jsl DecBusyFlg	rtl	ENDP	EXPORT oEndCall2oEndCall2	PROC	phd	EXPORT EndCall2EndCall2		;       	ldx #0	EXPORT ErrOut2ErrOut2		;       	pld	EXPORT oErrOut2oErrOut2		;       	ldy #2	jmp oErrOut	ENDP	EXPORT oBusyEC2oBusyEC2	PROC	phd	EXPORT BusyEC2BusyEC2		;       	ldx #0	EXPORT BusyErr2BusyErr2		;       	pld	EXPORT oBusyErr2oBusyErr2		;       	ldy #2	jmp oBusyErr	ENDP	EXPORT oEndCall4oEndCall4	PROC	phd	EXPORT EndCall4EndCall4		;       	ldx #0	EXPORT ErrOut4ErrOut4		;       	pld	EXPORT oErrOut4oErrOut4		;       	ldy #4	jmp oErrOut	ENDP	EXPORT oBusyEC4oBusyEC4	PROC	phd	EXPORT BusyEC4BusyEC4		;       	ldx #0	EXPORT BusyErr4BusyErr4		;       	pld	EXPORT oBusyErr4oBusyErr4		;       	ldy #4	jmp oBusyErr	ENDP	EXPORT oEndCall6oEndCall6	PROC	phd	EXPORT EndCall6EndCall6		;       	ldx #0	EXPORT ErrOut6ErrOut6		;       	pld	EXPORT oErrOut6oErrOut6		;       	ldy #6	jmp oErrOut	ENDP	EXPORT oBusyEC6oBusyEC6	PROC	phd	EXPORT BusyEC6BusyEC6		;       	ldx #0	EXPORT BusyErr6BusyErr6		;       	pld	EXPORT oBusyErr6oBusyErr6		;       	ldy #6	jmp oBusyErr	ENDP	EXPORT oEndCall8oEndCall8	PROC	phd	EXPORT EndCall8EndCall8		;       	ldx #0	EXPORT ErrOut8ErrOut8		;       	pld	EXPORT oErrOut8oErrOut8		;       	ldy #8	jmp oErrOut	ENDP	EXPORT oBusyEC8oBusyEC8	PROC	phd	EXPORT BusyEC8BusyEC8		;       	ldx #0	EXPORT BusyErr8BusyErr8		;       	pld	EXPORT oBusyErr8oBusyErr8		;       	ldy #8	jmp oBusyErr	ENDP	EXPORT oEndCall10oEndCall10	PROC	phd	EXPORT EndCall10EndCall10		;       	ldx #0	EXPORT ErrOut10ErrOut10		;       	pld	EXPORT oErrOut10oErrOut10		;       	ldy #10	jmp oErrOut	ENDP	EXPORT oBusyEC10oBusyEC10	PROC	phd	EXPORT BusyEC10BusyEC10		;       	ldx #0	EXPORT BusyErr10BusyErr10		;       	pld	EXPORT oBusyErr10oBusyErr10		;       	ldy #10	jmp oBusyErr	ENDP	EXPORT oEndCall12oEndCall12	PROC	phd	EXPORT EndCall12EndCall12		;       	ldx #0	EXPORT ErrOut12ErrOut12		;       	pld	EXPORT oErrOut12oErrOut12		;       	ldy #12	jmp oErrOut	ENDP	EXPORT oBusyEC12oBusyEC12	PROC	phd	EXPORT BusyEC12BusyEC12		;       	ldx #0	EXPORT BusyErr12BusyErr12		;       	pld	EXPORT oBusyErr12oBusyErr12		;       	ldy #12	jmp oBusyErr	ENDP	EXPORT oEndCall14oEndCall14	PROC	phd	EXPORT EndCall14EndCall14		;       	ldx #0	EXPORT ErrOut14ErrOut14		;       	pld	EXPORT oErrOut14oErrOut14		;       	ldy #14	jmp oErrOut	ENDP	EXPORT oBusyEC14oBusyEC14	PROC	phd	EXPORT BusyEC14BusyEC14		;       	ldx #0	EXPORT BusyErr14BusyErr14		;       	pld	EXPORT oBusyErr14oBusyErr14		;       	ldy #14	jmp oBusyErr	ENDP	EXPORT oEndCall16oEndCall16	PROC	phd	EXPORT EndCall16EndCall16		;       	ldx #0	EXPORT ErrOut16ErrOut16		;       	pld	EXPORT oErrOut16oErrOut16		;       	ldy #16	jmp oErrOut	ENDP	EXPORT oBusyEC16oBusyEC16	PROC	phd	EXPORT BusyEC16BusyEC16		;       	ldx #0	EXPORT BusyErr16BusyErr16		;       	pld	EXPORT oBusyErr16oBusyErr16		;       	ldy #16	jmp oBusyErr	ENDP	EXPORT StripStrip	PROC	EXPORT BusyECBusyEC		;       	ldx #0	EXPORT BusyErrBusyErr		;       	jsl DecBusyFlg	bra ErrOut	EXPORT EndCallEndCall		;       	ldx #0	EXPORT ErrOutErrOut		;       	pld	; restore direct register	EXPORT oErrOutoErrOut        		phy	; save amount to strip on stack	tsc	; get stack pointer	clc	; add to it the amount to strip	adc 1,s	tay	; put this result in Y	tsc	; get back orig stack pointer	phx	; save error on stack	tax	; put orig stack in	X	phb	; now save the data	bank reg	pea $0000	; set data bank reg	to 0	plb	plb	lda |3+4,x	;now use x and y to move 6 bytes	sta |3+4,y	; of rtl info from	current pos	lda |3+2,x	; to final pos.	sta |3+2,y	lda |3+0,x	sta |3+0,y	plb	; restore data bank	register	plx	; restore x register with error		tsc	; get stack again	clc	; bump it by amount	to strip Plus 2	adc 1,s	; to make up for amount to strip	adc #2	; still on stack	tcs	; reset stack pointer	txa	; error into a-reg	cmp #1	; set carry correctly	rtl	; fini					EXPORT oBusyECoBusyEC		;       	ldx #0	EXPORT oBusyErroBusyErr		;       	jsl DecBusyFlg	bra oErrOut	EXPORT oEndCalloEndCall		;       	ldx #0	bra oErrOut	ENDP	END